// Example: idempotent write to DynamoDB with conditional expression
async function upsertEvent(dynamo, key, item) {
  const params = {
    TableName: 'TelemetryState',
    Item: { ...key, ...item },
    ConditionExpression: 'attribute_not_exists(deviceId) OR :ts > ts',
    ExpressionAttributeValues: { ':ts': item.ts }
